#!/usr/bin/env python3
import os, base64

DIRS = ['prompts', 'src', 'streamlit', 'streamlit/pages', 'streamlit/streamlit_components']

FILES = {
    'README.md': '',
    'prompts/extraction_prompt.md': '',
    'prompts/issuance_extraction_prompt.md': '',
    'src/db_utils.py': '',
    'src/form_utils.py': '',
    'src/instantiate_llm.py': '',
    'src/issuance_extraction.py': '',
    'src/models.py': '',
    'src/utils.py': '',
    'streamlit/__init__.py': 'IA==',
    'streamlit/home.py': '',
    'streamlit/pages/create_new_issuance.py': '',
    'streamlit/pages/manage_activities.py': '',
    'streamlit/pages/manage_issuances.py': 'aW1wb3J0IHN0cmVhbWxpdCBhcyBzdAoKc3Quc2V0X3BhZ2VfY29uZmlnKHBhZ2VfdGl0bGU9Ik1hbmFnZSBJc3N1YW5jZSIpCnN0LnRpdGxlKCLwn5eC77iPIE1hbmFnZSBJc3N1YW5jZSIpCnN0LndyaXRlKCJIZXJlIGlzIHdoZXJlIHlvdSdsbCBtYW5hZ2UgZXhpc3RpbmcgaXNzdWFuY2VzLiIpCg==',
    'streamlit/streamlit_components/__init__.py': '',
    'streamlit/streamlit_components/render_full_issuance_form.py': '',
    'streamlit/streamlit_components/render_initial_issuance_form.py': '',
    'streamlit/streamlit_utils.py': '',
    'summarizer_original.py': '',
}

def main():
    # Create directories
    for d in DIRS:
        os.makedirs(d, exist_ok=True)

    # Write files
    for path, b64 in FILES.items():
        data = base64.b64decode(b64)
        full_path = os.path.abspath(path)
        dirpath = os.path.dirname(full_path)
        os.makedirs(dirpath, exist_ok=True)
        with open(full_path, "wb") as f:
            f.write(data)

if __name__ == "__main__":
    main()
